create extension if not exists pgcrypto;
create type app_role as enum ('super_admin','state_admin','enumerator','citizen');
create type app_status as enum ('draft','submitted','under_review','approved','rejected','disbursed');
create table roles(id uuid primary key default gen_random_uuid(), name app_role unique not null);
create table states(id uuid primary key default gen_random_uuid(), name text unique not null, code text unique);
create table lgas(id uuid primary key default gen_random_uuid(), state_id uuid references states(id) on delete cascade, name text not null, unique(state_id,name));
create table wards(id uuid primary key default gen_random_uuid(), lga_id uuid references lgas(id) on delete cascade, name text not null, unique(lga_id,name));
create table users(id uuid primary key references auth.users(id) on delete cascade, email text unique not null, full_name text not null, role app_role not null, state_id uuid references states(id), is_active boolean default true, created_at timestamptz default now());
create table enumerators(id uuid primary key default gen_random_uuid(), user_id uuid unique references users(id) on delete cascade, state_id uuid references states(id), employee_code text unique, created_at timestamptz default now());
create table applications(id uuid primary key default gen_random_uuid(), application_id text unique not null, full_name text not null, gender text not null, date_of_birth date not null, phone_number text not null, phone_hash text unique not null, email text, nin_encrypted text not null, nin_hash text unique not null, bvn_encrypted text not null, bvn_hash text unique not null, state_id uuid references states(id), lga_id uuid references lgas(id), ward_id uuid references wards(id), residential_address text not null, marital_status text not null, occupation text not null, household_size int not null check(household_size>0), number_of_dependents int not null check(number_of_dependents>=0), monthly_income_range text not null, disability_status text, bank_name text not null, account_name text not null, account_number_encrypted text not null, account_number_hash text unique not null, status app_status default 'submitted', enumerator_id uuid references users(id), created_at timestamptz default now(), updated_at timestamptz default now());
create table consent_signatures(id uuid primary key default gen_random_uuid(), application_id uuid unique references applications(id) on delete cascade, accepted boolean not null, signature_type text not null check(signature_type in('drawn','typed')), signature_data text not null, ip_address inet, user_agent text, enumerator_id uuid references users(id), session_id text, created_at timestamptz default now());
create table application_status_history(id uuid primary key default gen_random_uuid(), application_id uuid references applications(id) on delete cascade, previous_status app_status, new_status app_status not null, changed_by uuid references users(id), reason text, created_at timestamptz default now());
create table registration_lock_codes(id uuid primary key default gen_random_uuid(), state_id uuid references states(id), code_hash text unique not null, is_active boolean default true, expires_at timestamptz not null, created_by uuid references users(id), created_at timestamptz default now());
create table registration_access_attempts(id uuid primary key default gen_random_uuid(), user_id uuid references users(id), state_id uuid references states(id), ip_address text, user_agent text, device_info jsonb, success boolean not null, created_at timestamptz default now());
create table sms_logs(id uuid primary key default gen_random_uuid(), application_id text, recipient text not null, message text not null, status text default 'queued', attempts int default 0, error text, sent_at timestamptz, created_at timestamptz default now());
create table email_logs(id uuid primary key default gen_random_uuid(), application_id text, recipient text not null, subject text not null, pdf_path text, status text default 'queued', attempts int default 0, error text, sent_at timestamptz, created_at timestamptz default now());
create table pdf_records(id uuid primary key default gen_random_uuid(), application_id uuid references applications(id) on delete cascade, file_path text not null, created_at timestamptz default now());
create table audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references users(id), event text not null, metadata jsonb default '{}', ip_address text, user_agent text, created_at timestamptz default now());
create table notifications(id uuid primary key default gen_random_uuid(), user_id uuid references users(id), title text not null, body text not null, read_at timestamptz, created_at timestamptz default now());
create index applications_state_status_idx on applications(state_id,status); create index applications_created_idx on applications(created_at desc); create index audit_logs_event_idx on audit_logs(event,created_at desc); create index lock_active_idx on registration_lock_codes(is_active,expires_at);
alter table users enable row level security; alter table applications enable row level security; alter table consent_signatures enable row level security; alter table audit_logs enable row level security;
create policy users_self on users for select using (auth.uid()=id or exists(select 1 from users u where u.id=auth.uid() and u.role='super_admin'));
create policy apps_staff_state on applications for select using (exists(select 1 from users u where u.id=auth.uid() and (u.role='super_admin' or (u.state_id=applications.state_id and u.role in('state_admin','enumerator')))));
create policy apps_insert_enum on applications for insert with check (exists(select 1 from users u where u.id=auth.uid() and u.role in('super_admin','state_admin','enumerator') and (u.role='super_admin' or u.state_id=state_id)));
insert into roles(name) values ('super_admin'),('state_admin'),('enumerator'),('citizen') on conflict do nothing;
